/**
 * The shell-shock environment configuration object.
 *
 * @remarks
 * This object provides access to the shell-shock environment configuration parameters in the application runtime.
 */
export const env: Env = createEnv(process.env as Partial<Env>);

/**
 * Detect if the application is running in a continuous integration (CI) environment.
 */
export const isCI = Boolean(
  env.CI ||
  env.RUN_ID ||
  env.AGOLA_GIT_REF ||
  env.AC_APPCIRCLE ||
  env.APPVEYOR ||
  env.CODEBUILD ||
  env.TF_BUILD ||
  env.bamboo_planKey ||
  env.BITBUCKET_COMMIT ||
  env.BITRISE_IO ||
  env.BUDDY_WORKSPACE_ID ||
  env.BUILDKITE ||
  env.CIRCLECI ||
  env.CIRRUS_CI ||
  env.CF_BUILD_ID ||
  env.CM_BUILD_ID ||
  env.CI_NAME ||
  env.DRONE ||
  env.DSARI ||
  env.EARTHLY_CI ||
  env.EAS_BUILD ||
  env.GERRIT_PROJECT ||
  env.GITEA_ACTIONS ||
  env.GITHUB_ACTIONS ||
  env.GITLAB_CI ||
  env.GOCD ||
  env.BUILDER_OUTPUT ||
  env.HARNESS_BUILD_ID ||
  env.JENKINS_URL ||
  env.LAYERCI ||
  env.MAGNUM ||
  env.NETLIFY ||
  env.NEVERCODE ||
  env.PROW_JOB_ID ||
  env.RELEASE_BUILD_ID ||
  env.RENDER ||
  env.SAILCI ||
  env.HUDSON ||
  env.SCREWDRIVER ||
  env.SEMAPHORE ||
  env.SOURCEHUT ||
  env.STRIDER ||
  env.TASK_ID ||
  env.RUN_ID ||
  env.TEAMCITY_VERSION ||
  env.TRAVIS ||
  env.VELA ||
  env.NOW_BUILDER ||
  env.APPCENTER_BUILD_ID ||
  env.CI_XCODE_PROJECT ||
  env.XCS ||
  false
);

/**
 * Detect the \`mode\` of the current runtime environment.
 *
 * @remarks
 * The `mode` is determined by the `MODE` environment variable, or falls back to the `NEXT_PUBLIC_VERCEL_ENV`, `NODE_ENV`, or defaults to `production`. While the value can potentially be any string, it is generally recommended to only allow a value in the following list:
 *
 * - `production`
 *
 * - `test`
 *
 * - `development`
 */
export const mode = String(env.MODE) || "production";

/**
 * Detect if the application is running in `"production"` mode
 */
export const isProduction = ["prd", "prod", "production"].includes(
  mode.toLowerCase()
);

/**
 * Detect if the application is running in `"test"` mode
 */
export const isTest =
  ["tst", "test", "testing", "stg", "stage", "staging"].includes(
    mode.toLowerCase()
  ) || env.TEST;

/**
 * Detect if the application is running in `"development"` mode
 */
export const isDevelopment = ["dev", "development"].includes(
  mode.toLowerCase()
);

/**
 * Detect if the application is currently being debugged
 */
export const isDebug = Boolean(isDevelopment && env.DEBUG);

/**
 * An indicator specifying whether the current operating system is MacOS (darwin kernel).
 */
export const isWindows = /^win/i.test(process.platform);

/**
 * An indicator specifying whether the current operating system is Linux.
 */
export const isLinux = /^linux/i.test(process.platform);

/**
 * An indicator specifying whether the current operating system is MacOS (darwin kernel).
 */
export const isMacOS = /^darwin/i.test(process.platform);

const homedir = os.homedir();

const tmpdir = os.tmpdir();

/**
 * The environment path types for storing things like data, config, logs, and cache in the current runtime environment.
 *
 * @remarks
 * These environment path types are accessed in the {@link EnvPaths} type.
 */
export type EnvPathType = "data" | "config" | "cache" | "log" | "temp";

/**
 * The environment paths for storing things like data, config, logs, and cache in the current runtime environment.
 */
export type EnvPaths = Record<EnvPathType, string>;

/**
 * The resolved application directories based on the current operating system and environment variables.
 *
 * @remarks
 * If the `DATA_DIR`, `CONFIG_DIR`, `CACHE_DIR`, `LOG_DIR`, or `TEMP_DIR` environment variables are set, they will be treated as overrides and used by default. If the environment variables are not set, the paths are determined based on the specific conventions for each operating system (with additional overrides available through operating system specific environment variables):
 *
 * - **Linux**: directories are generally created in `~/.config/<name>` (this is determined via the [XDG Base Directory spec](https://specifications.freedesktop.org/basedir-spec/latest/))
 *
 * - **Windows**: directories are generally created in `%AppData%/<name>`
 *
 * - **MacOS**: directories are generally created in `~/Library/Application Support/<name>`
 */
export const paths = isMacOS
  ? {
      data: env.DATA_DIR
        ? join(String(env.DATA_DIR), "Powerlines")
        : join(
            homedir,
            "Library",
            "Application Support",
            "Storm Software",
            "Powerlines"
          ),
      config: env.CONFIG_DIR
        ? join(String(env.CONFIG_DIR), "Powerlines")
        : join(
            homedir,
            "Library",
            "Preferences",
            "Storm Software",
            "Powerlines"
          ),
      cache: env.CACHE_DIR
        ? join(String(env.CACHE_DIR), "Powerlines")
        : join(homedir, "Library", "Caches", "Storm Software", "Powerlines"),
      log: env.LOG_DIR
        ? join(String(env.LOG_DIR), "Powerlines")
        : join(homedir, "Library", "Logs", "Storm Software", "Powerlines"),
      temp: env.TEMP_DIR
        ? join(String(env.TEMP_DIR), "Powerlines")
        : join(tmpdir, "Storm Software", "Powerlines")
    }
  : isWindows
    ? {
        data: env.DATA_DIR
          ? join(String(env.DATA_DIR), "Powerlines")
          : join(
              env.LOCALAPPDATA || join(homedir, "AppData", "Local"),
              "Storm Software",
              "Powerlines",
              "Data"
            ),
        config: env.CONFIG_DIR
          ? join(env.CONFIG_DIR!, "Powerlines")
          : join(
              env.APPDATA || join(homedir, "AppData", "Roaming"),
              "Storm Software",
              "Powerlines",
              "Config"
            ),
        cache: env.CACHE_DIR
          ? join(String(env.CACHE_DIR), "Powerlines")
          : join(
              env.LOCALAPPDATA || join(homedir, "AppData", "Local"),
              "Cache",
              "Storm Software",
              "Powerlines"
            ),
        log: env.LOG_DIR
          ? join(String(env.LOG_DIR), "Powerlines")
          : join(
              env.LOCALAPPDATA || join(homedir, "AppData", "Local"),
              "Storm Software",
              "Powerlines",
              "Log"
            ),
        temp: env.TEMP_DIR
          ? join(String(env.TEMP_DIR), "Powerlines")
          : join(tmpdir, "Storm Software", "Powerlines")
      }
    : ({
        data: env.DATA_DIR
          ? join(String(env.DATA_DIR), "powerlines")
          : join(
              env.XDG_DATA_HOME || join(homedir, ".local", "share"),
              "storm-software",
              "powerlines"
            ),
        config: env.CONFIG_DIR
          ? join(String(env.CONFIG_DIR), "powerlines")
          : join(
              env.XDG_CONFIG_HOME || join(homedir, ".config"),
              "storm-software",
              "powerlines"
            ),
        cache: env.CACHE_DIR
          ? join(String(env.CACHE_DIR), "powerlines")
          : join(
              env.XDG_CACHE_HOME || join(homedir, ".cache"),
              "storm-software",
              "powerlines"
            ),
        log: env.LOG_DIR
          ? join(String(env.LOG_DIR), "powerlines")
          : join(
              env.XDG_STATE_HOME || join(homedir, ".local", "state"),
              "storm-software",
              "powerlines"
            ),
        temp: env.TEMP_DIR
          ? join(String(env.TEMP_DIR), "powerlines")
          : env.DEVENV_RUNTIME || env.XDG_RUNTIME_DIR
            ? join(
                (env.DEVENV_RUNTIME || env.XDG_RUNTIME_DIR)!,
                "storm-software",
                "powerlines"
              )
            : join(tmpdir, basename(homedir), "storm-software", "powerlines")
      } as EnvPaths);
